func:
// ================= PARSING AMAN =================
if (typeof msg.payload === "string") {
    if (!msg.payload.trim().startsWith("{")) return null;

    try {
        msg.payload = JSON.parse(msg.payload);
    } catch (e) {
        return null;
    }
}

let d = msg.payload;

// ================= VALIDASI =================
const required = ["suhu_kompos", "kelembapan_kompos"];
for (let f of required) {
    if (d[f] === undefined || d[f] === null) return null;
}

// ================= NORMALISASI =================
let suhu = parseFloat(d.suhu_kompos);
let hum = parseInt(d.kelembapan_kompos);
let suhu_udara = parseFloat(d.suhu_udara);
let hum_udara = parseInt(d.kelembapan_udara);

if (isNaN(suhu) || isNaN(hum)) return null;

if (isNaN(suhu_udara)) suhu_udara = 0;
if (isNaN(hum_udara)) hum_udara = 0;

// ================= SYNC MODE DARI ESP32 =================
let currentMode = d.mode || "AUTO";
global.set("mode", currentMode);
d.mode = currentMode;

// ================= THRESHOLD =================
const suhuMin = 30;
const suhuMax = 45;
const humMin = 40;
const humMax = 60;

const suhuMinOut = 29;
const suhuMaxOut = 46;
const humMinOut = 38;
const humMaxOut = 62;

// ================= STATUS SENSOR =================
let suhu_status = (suhu >= suhuMin && suhu <= suhuMax)
    ? "✅ OPTIMAL"
    : "⚠️ TIDAK OPTIMAL";

let lembab_status = (hum >= humMin && hum <= humMax)
    ? "✅ OPTIMAL"
    : "⚠️ TIDAK OPTIMAL";

// ================= HYSTERESIS STATUS =================
let lastStatus = global.get("statusHysteresis") || "OPTIMAL";
let status;

if (suhu > 50 || hum < 30 || hum > 75) {
    status = "KRITIS";
} else {
    if (lastStatus === "OPTIMAL") {
        if (
            suhu < suhuMinOut ||
            suhu > suhuMaxOut ||
            hum < humMinOut ||
            hum > humMaxOut
        ) {
            status = "TIDAK OPTIMAL";
        } else {
            status = "OPTIMAL";
        }
    } else {
        if (
            suhu >= suhuMin &&
            suhu <= suhuMax &&
            hum >= humMin &&
            hum <= humMax
        ) {
            status = "OPTIMAL";
        } else {
            status = "TIDAK OPTIMAL";
        }
    }
}

global.set("statusHysteresis", status);

// ================= SIMPAN DATA =================
d.suhu_status = suhu_status;
d.lembab_status = lembab_status;
d.status = status;

global.set("lastData", d);

// ================= OUTPUT =================
return [
    // 1. Gauge kelembapan kompos
    { payload: hum },

    // 2. Gauge suhu kompos
    { payload: suhu },

    // 3. Gauge kelembapan udara
    { payload: hum_udara },

    // 4. Gauge suhu udara
    { payload: suhu_udara },

    // 5. Status pompa
    { payload: d.pompa == 1 ? "🟢 ON" : "🔴 OFF" },

    // 6. Status kipas
    { payload: d.kipas == 1 ? "🟢 ON" : "🔴 OFF" },

    // 7. Mode
    { payload: currentMode },

    // 8. Status sistem
    { payload: status },

    // 9. RAW data untuk Function Chart / Function Firebase / Debug
    { payload: d }
];

// ================= CEK SISTEM =================
let systemOn = global.get("systemOn");

if (systemOn === undefined) {
    systemOn = true;
    global.set("systemOn", true);
}

if (!systemOn) return null;

// ================= AMBIL DATA =================
let d = msg.payload;

if (!d || d.suhu_kompos === undefined) {
    d = global.get("lastData");
}

if (!d || d.suhu_kompos === undefined) return null;

// ================= VALIDASI ANGKA =================
let suhu = parseFloat(d.suhu_kompos);
let hum = parseInt(d.kelembapan_kompos);

if (isNaN(suhu) || isNaN(hum)) return null;

// ================= AMBIL MODE & STATUS =================
let mode = d.mode || global.get("mode") || "AUTO";
let status = d.status || global.get("statusHysteresis") || "OPTIMAL";

let anomaly = global.get("lastAnomaly") || false;

// ================= STABILISASI STATUS =================
// Supaya notifikasi tidak langsung dikirim karena noise sesaat
let lastRawStatus = global.get("lastRawStatus") || null;
let counter = global.get("statusCounter") || 0;

if (status === lastRawStatus) {
    counter++;
} else {
    counter = 0;
}

global.set("lastRawStatus", status);
global.set("statusCounter", counter);

// Status harus stabil beberapa kali dulu
if (counter < 3) return null;

// ================= FILTER DUPLIKAT =================
let lastSent = global.get("lastStatusSent");

if (status === lastSent && !anomaly) {
    return null;
}

// ================= ANTI SPAM GLOBAL =================
let lastTime = global.get("lastNotifTime") || 0;
let now = Date.now();

if (now - lastTime < 30000) {
    return null;
}

// ================= FORMAT DASAR =================
const garis = "━━━━━━━━━━━━━━━";

let judul = "";
let ikonStatus = "";
let rekomendasi = "";

// ================= TENTUKAN JUDUL =================
if (anomaly) {
    judul = "⚠️ PERINGATAN PERUBAHAN TIDAK WAJAR";
    ikonStatus = "⚠️ ANOMALI";
}
else if (status === "KRITIS") {
    judul = "🔴 KONDISI KRITIS";
    ikonStatus = "🔴 KRITIS";
}
else if (status === "TIDAK OPTIMAL" || status === "TDK OPT") {
    judul = "🟡 KONDISI TIDAK OPTIMAL";
    ikonStatus = "🟡 TIDAK OPTIMAL";
}
else {
    judul = "🟢 KONDISI OPTIMAL";
    ikonStatus = "🟢 OPTIMAL";
}

// ================= REKOMENDASI =================
if (anomaly) {
    rekomendasi =
        "Terjadi perubahan data yang tidak wajar.\n" +
        "Rekomendasi:\n" +
        "- Periksa sensor\n" +
        "- Periksa kabel dan koneksi\n" +
        "- Amati kondisi kompos secara langsung";
}
else if (status === "OPTIMAL") {
    rekomendasi =
        "Proses pengomposan berada dalam kondisi baik. Pertahankan kondisi suhu dan kelembapan media kompos.";
}
else {
    // ===== MODE MANUAL =====
    if (mode === "MANUAL") {
        if (suhu < 30) {
            rekomendasi =
                "Suhu kompos rendah. Proses dekomposisi dapat berjalan lebih lambat.\n" +
                "Saran: tambahkan bahan hijau, aduk kompos, atau tempatkan kompos di area yang lebih hangat.";
        }
        else if (suhu > 45) {
            rekomendasi =
                "Suhu kompos tinggi.\n" +
                "Saran: nyalakan kipas beberapa saat untuk membantu sirkulasi udara dan menurunkan suhu.";
        }
        else if (hum < 40) {
            rekomendasi =
                "Kelembapan kompos rendah.\n" +
                "Saran: nyalakan pompa sekitar 10 detik atau tambahkan air secukupnya.";
        }
        else if (hum > 60) {
            rekomendasi =
                "Kelembapan kompos terlalu tinggi.\n" +
                "Saran: hentikan penyiraman, aduk kompos, dan tingkatkan aerasi.";
        }
        else {
            rekomendasi =
                "Kondisi berada di luar batas ideal. Lakukan pengecekan langsung pada media kompos.";
        }
    }

    // ===== MODE AUTO =====
    else {
        if (suhu < 30) {
            rekomendasi =
                "Suhu kompos rendah. Sistem belum memiliki aktuator pemanas, sehingga diperlukan tindakan manual seperti menambah bahan hijau, mengaduk kompos, atau menempatkan kompos di area yang lebih hangat.";
        }
        else if (suhu > 45) {
            rekomendasi =
                "Suhu kompos tinggi. Pada mode otomatis, sistem akan mengaktifkan kipas untuk membantu menurunkan suhu dan meningkatkan sirkulasi udara.";
        }
        else if (hum < 40) {
            rekomendasi =
                "Kelembapan kompos rendah. Pada mode otomatis, sistem akan mengaktifkan pompa sesuai durasi dan jeda yang telah ditentukan.";
        }
        else if (hum > 60) {
            rekomendasi =
                "Kelembapan kompos terlalu tinggi. Sistem akan menghentikan penyiraman. Perlu pengecekan manual agar media kompos tidak terlalu basah.";
        }
        else {
            rekomendasi =
                "Sistem sedang menyesuaikan kondisi secara otomatis.";
        }
    }
}

// ================= FORMAT MODE =================
let modeText = mode === "MANUAL" ? "✋ MANUAL" : "🔁 AUTO";

// ================= FORMAT PESAN =================
let pesan =
    judul + "\n" +
    garis + "\n\n" +

    "🌡️ Suhu Kompos      : " + suhu.toFixed(1) + " °C (optimal 30–45°C)\n" +
    "💧 Kelembapan Kompos: " + hum + " % (optimal 40–60%)\n\n" +

    garis + "\n\n" +

    "🔧 Mode             : " + modeText + "\n" +
    "📌 Status           : " + ikonStatus + "\n\n" +

    garis + "\n\n" +

    "💡 Rekomendasi:\n" +
    rekomendasi;

// ================= OUTPUT TELEGRAM =================
msg.payload = {
    chatId: "5276386835",
    type: "message",
    content: pesan
};

// ================= SIMPAN STATUS =================
global.set("lastStatusSent", status);
global.set("lastNotifTime", now);

return msg;

let d = msg.payload;

if (!d) return null;

let suhu = parseFloat(d.suhu_kompos);
let suhu_udara = parseFloat(d.suhu_udara);
let hum = parseInt(d.kelembapan_kompos);
let hum_udara = parseInt(d.kelembapan_udara);

if (isNaN(suhu)) return null;
if (isNaN(hum)) return null;

if (isNaN(suhu_udara)) suhu_udara = 0;
if (isNaN(hum_udara)) hum_udara = 0;

let now = Date.now();

return [
    { topic: "Suhu Kompos", payload: { x: now, y: suhu } },
    { topic: "Suhu Udara", payload: { x: now, y: suhu_udara } },
    { topic: "Kelembapan Kompos", payload: { x: now, y: hum } },
    { topic: "Kelembapan Udara", payload: { x: now, y: hum_udara } }
];

// ================= WHITELIST CHAT ID =================
const ALLOWED_CHAT_IDS = ["5276386835"]; // tambahkan chatId lain di sini

// ================= VALIDASI =================
if (!msg.payload || !msg.payload.content || !msg.payload.chatId) {
    return null;
}

let text = msg.payload.content.trim().toLowerCase();
let chatId = msg.payload.chatId;

// ================= CEK KEAMANAN =================
if (!ALLOWED_CHAT_IDS.includes(String(chatId))) {
    return [null, {
        payload: {
            chatId: chatId,
            type: "message",
            content: "⛔ Akses tidak diizinkan."
        }
    }];
}

const garis = "━━━━━━━━━━━━━━━";

// ================= HELPER =================
function kirimTelegram(pesan) {
    return {
        payload: {
            chatId: chatId,
            type: "message",
            content: pesan
        }
    };
}

function kirimMQTT(command) {
    return {
        payload: command,
        topic: "iot/kompos/ta/device1/control"
    };
}

// ================= /help =================
if (text === "/help") {
    let pesan =
        "📖 PANDUAN PERINTAH\n" +
        garis + "\n\n" +
        "📊 Info & Status\n" +
        "/info    — Data sensor terkini\n" +
        "/status  — Status notifikasi & kondisi\n\n" +
        garis + "\n\n" +
        "🔔 Notifikasi\n" +
        "/on   — Aktifkan notifikasi\n" +
        "/off  — Matikan notifikasi\n\n" +
        garis + "\n\n" +
        "⚙️ Mode Operasi\n" +
        "/auto    — Mode otomatis\n" +
        "/manual  — Mode manual\n\n" +
        garis + "\n\n" +
        "🎛️ Kontrol Manual\n" +
        "(Aktifkan /manual terlebih dahulu)\n" +
        "/pompa_on  — Nyalakan pompa\n" +
        "/pompa_off — Matikan pompa\n" +
        "/kipas_on    — Nyalakan kipas\n" +
        "/kipas_off   — Matikan kipas";

    return [null, kirimTelegram(pesan)];
}
if (text === "/info") {
    let d = global.get("lastData");

    if (!d || !d.suhu_status || !d.lembab_status) {
        return [null, kirimTelegram("⚠️ Data belum siap. Tunggu sensor update.")];
    }

    let suhuVal = parseFloat(d.suhu_kompos);
    let humVal  = parseInt(d.kelembapan_kompos);

    let suhu = suhuVal.toFixed(1);
    let hum  = humVal;

    let pompaText = d.pompa == 1 ? "🟢 ON" : "🔴 OFF";
    let kipasText = d.kipas == 1 ? "🟢 ON" : "🔴 OFF";
    let modeText = (d.mode === "MANUAL") ? "✋ MANUAL" : "🔁 AUTO";

    // ================= IKON STATUS =================
    let ikonStatus;
    if (d.status === "KRITIS") ikonStatus = "🔴 KRITIS";
    else if (d.status === "TIDAK OPTIMAL") ikonStatus = "🟡 TIDAK OPTIMAL";
    else ikonStatus = "🟢 OPTIMAL";

    // ================= INSIGHT =================
    let insight = "";

    if (suhuVal < 30) {
        insight = "Kompos terlalu dingin → proses lambat.\n💡 Saran: tambahkan bahan hijau / aduk kompos.";
    }
    else if (suhuVal > 45) {
        insight = "Kompos terlalu panas.\n💡 Saran: aktifkan kipas atau kurangi kelembapan.";
    }
    else if (humVal < 40) {
        insight = "Kompos terlalu kering.\n💡 Saran: nyalakan pompa ±10 detik.";
    }
    else if (humVal > 60) {
        insight = "Kompos terlalu basah.\n💡 Saran: hentikan pompa & tambah aerasi.";
    }
    else {
        insight = "Kondisi ideal. Pertahankan 👍";
    }

    let pesan =
        "📊 DATA TERKINI\n" +
        garis + "\n\n" +

        "🌡️ Suhu kompos  : " + suhu + "°C (optimal 30–45°C)\n" +
        d.suhu_status + "\n\n" +

        "💧 Kelembapan   : " + hum + "% (optimal 40–60%)\n" +
        d.lembab_status + "\n\n" +

        "🌤️ Suhu udara   : " + d.suhu_udara + "°C\n" +
        "💨 Hum udara    : " + d.kelembapan_udara + "%\n\n" +

        garis + "\n\n" +

        "⚙️ Pompa        : " + pompaText + "\n" +
        "⚙️ Kipas        : " + kipasText + "\n" +
        "🔧 Mode         : " + modeText + "\n\n" +

        garis + "\n" +
        "📌 Status       : " + ikonStatus + "\n\n" +
        "💡 Analisis:\n" + insight;

    return [null, kirimTelegram(pesan)];
}
// ================= /on =================
if (text === "/on") {
    global.set("systemOn", true);
    return [null, kirimTelegram("✅ Notifikasi AKTIF")];
}

// ================= /off =================
if (text === "/off") {
    global.set("systemOn", false);
    return [null, kirimTelegram("⛔ Notifikasi DIMATIKAN")];
}

// ================= /status =================
if (text === "/status") {
    let on = global.get("systemOn");
    let d = global.get("lastData");

    let ikonStatus = "⚠️ Belum ada data";
    if (d && d.status) {
        if (d.status === "KRITIS") ikonStatus = "🔴 KRITIS";
        else if (d.status === "TIDAK OPTIMAL") ikonStatus = "🟡 TIDAK OPTIMAL";
        else ikonStatus = "🟢 OPTIMAL";
    }

    return [null, kirimTelegram(
        "🔧 Notifikasi : " + (on ? "AKTIF" : "MATI") + "\n" +
        "📌 Status     : " + ikonStatus
    )];
}

// ================= MODE =================
if (text === "/manual") {
    global.set("mode", "MANUAL");
    return [
        kirimMQTT("MANUAL"),
        kirimTelegram(
            "✋ MODE MANUAL AKTIF\n\n" +
            "Perintah:\n" +
            "/pompa_on\n/pompa_off\n/kipas_on\n/kipas_off"
        )
    ];
}

if (text === "/auto") {
    global.set("mode", "AUTO");
    return [kirimMQTT("AUTO"), kirimTelegram("🔁 MODE AUTO AKTIF")];
}

// ================= VALIDASI MODE =================
let mode = global.get("mode") || "AUTO";

function cekManual() {
    if (mode !== "MANUAL") {
        return [null, kirimTelegram("⚠️ Aktifkan MODE MANUAL dulu dengan /manual")];
    }
    return null;
}

// ================= POMPA =================
if (text === "/pompa_on") {
    let cek = cekManual();
    if (cek) return cek;
    return [kirimMQTT("POMPA_ON"), kirimTelegram("💧 Pompa ON")];
}

if (text === "/pompa_off") {
    let cek = cekManual();
    if (cek) return cek;
    return [kirimMQTT("POMPA_OFF"), kirimTelegram("💧 Pompa OFF")];
}

// ================= kipas =================
if (text === "/kipas_on") {
    let cek = cekManual();
    if (cek) return cek;
    return [kirimMQTT("KIPAS_ON"), kirimTelegram("🌀 kipas ON")];
}

if (text === "/kipas_off") {
    let cek = cekManual();
    if (cek) return cek;
    return [kirimMQTT("KIPAS_OFF"), kirimTelegram("🌀 kipas OFF")];
}

// ================= DEFAULT =================
return [null, kirimTelegram(
    "❓ Perintah tidak dikenal.\n\nKetik /help untuk daftar perintah."
)];

// ================= CEK SISTEM =================
let systemOn = global.get("systemOn");
if (systemOn === false) return null;

// ================= AMBIL DATA =================
let d = global.get("lastData");

if (!d) {
    return {
        payload: {
            chatId: "5276386835",
            type: "message",
            content: "⚠️ Data belum tersedia. Tunggu sensor update."
        }
    };
}

// ================= AMBIL STATUS ANOMALI =================
let anomaly = global.get("lastAnomaly") || false;

// ================= FORMAT ANGKA =================
let suhuVal = parseFloat(d.suhu_kompos);
let humVal  = parseInt(d.kelembapan_kompos);

let suhu = suhuVal.toFixed(1); // untuk tampilan
let hum  = humVal;

// ================= STATUS =================
let suhuStatus   = d.suhu_status  || "⚠️ STATUS BELUM TERSEDIA";
let lembabStatus = d.lembab_status || "⚠️ STATUS BELUM TERSEDIA";

// ================= IKON =================
let ikonStatus;
if (anomaly) ikonStatus = "⚠️ PERUBAHAN TIDAK WAJAR";
else if (d.status === "KRITIS") ikonStatus = "🔴 KRITIS";
else if (d.status === "TIDAK OPTIMAL") ikonStatus = "🟡 TIDAK OPTIMAL";
else ikonStatus = "🟢 OPTIMAL";

// ================= INTERPRETASI =================
let insight = "";

if (anomaly) {
    insight = "Terjadi perubahan data signifikan dalam waktu singkat. Perlu pengecekan sensor atau kondisi kompos.";
}
else if (suhuVal < 30) {
    insight = "Suhu relatif rendah, kemungkinan fase awal atau pendinginan.";
}
else if (suhuVal > 45) {
    insight = "Suhu tinggi, proses penguraian sedang aktif.";
}
else {
    insight = "Suhu berada dalam rentang optimal.";
}

// ================= AKTUATOR =================
let pompaText = d.pompa == 1 ? "🟢 ON" : "🔴 OFF";
let kipasText   = d.kipas   == 1 ? "🟢 ON" : "🔴 OFF";

const garis = "━━━━━━━━━━━━━━━";

// ================= PESAN =================
msg.payload = {
    chatId: "5276386835",
    type: "message",
    content:
        "📋 LAPORAN BERKALA SISTEM KOMPOSTER\n" +
        garis + "\n\n" +

        "🌡️ Suhu kompos  : " + suhu + "°C (optimal 30–45°C)\n" +
        suhuStatus + "\n\n" +

        "💧 Kelembapan   : " + hum + "% (optimal 40–60%)\n" +
        lembabStatus + "\n\n" +

        garis + "\n\n" +

        "🌤️ Suhu udara   : " + d.suhu_udara + "°C\n" +
        "💨 Hum udara    : " + d.kelembapan_udara + "%\n\n" +

        garis + "\n\n" +

        "⚙️ Pompa        : " + pompaText + "\n" +
        "⚙️ Kipas        : " + kipasText + "\n\n" +

        garis + "\n" +

        "📌 Status       : " + ikonStatus + "\n\n" +
        "💡 Analisis     : " + insight
};

return msg;

let data = msg.payload;


let waktu = new Date().toLocaleString("id-ID", {
    timeZone: "Asia/Jakarta",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit"
});

let firebaseData = {
    suhu_kompos: data.suhu_kompos,
    suhu_udara: data.suhu_udara,
    kelembapan_udara: data.kelembapan_udara,
    kelembapan_kompos: data.kelembapan_kompos,
    pompa: data.pompa,
    kipas: data.kipas,
    mode: data.mode,
    status: data.status,
    waktu: waktu
};

// Output 1 untuk lastData
let msgLastData = {
    payload: firebaseData
};

// Output 2 untuk history
let msgHistory = {
    payload: firebaseData
};

return [msgLastData, msgHistory];
